#!/usr/bin/env python3
"""Extractor de datos estructurados de documentos de texto (API de Anthropic).

Uso:
  python extractor.py factura.txt
  python extractor.py --carpeta ./documentos --salida ./extraidos

Requisitos:
  pip install anthropic
  export ANTHROPIC_API_KEY="tu-clave"

Trabaja sobre .txt. Si tienes PDF, conviértelo antes (p. ej. pdftotext factura.pdf).
"""

import argparse
import json
import os
import re
import sys
from pathlib import Path

try:
    import anthropic
except ImportError:
    sys.exit("Falta el SDK de Anthropic. Instálalo con: pip install anthropic")

# ── Configuración: define AQUÍ qué extraes ──────────────────────────────

MODELO = "claude-haiku-4-5"  # extraer campos es tarea de modelo pequeño
MAX_CARACTERES = 60000

SISTEMA = (
    "Eres un extractor de datos de documentos administrativos en español. "
    "Extrae EXCLUSIVAMENTE lo que el documento dice, llamando a la herramienta. "
    "Regla de oro: si un campo no aparece en el documento, devuélvelo como null. "
    "Nunca deduzcas, calcules ni completes datos que no estén escritos. "
    "En cada campo con valor, la cita es el fragmento literal del documento "
    "del que lo has sacado."
)

# Cada campo lleva su cita. Adapta propiedades y required a tus documentos.
CAMPO_CON_CITA = lambda tipo, descripcion: {
    "type": "object",
    "properties": {
        "valor": {"type": [tipo, "null"], "description": descripcion},
        "cita": {
            "type": ["string", "null"],
            "description": "Fragmento literal del documento de donde sale el valor.",
        },
    },
    "required": ["valor", "cita"],
    "additionalProperties": False,
}

HERRAMIENTA = {
    "name": "registrar_datos",
    "description": "Registra los datos extraídos del documento.",
    "strict": True,
    "input_schema": {
        "type": "object",
        "properties": {
            "tipo_documento": {
                "type": "string",
                "enum": ["factura", "albaran", "presupuesto", "contrato", "otro"],
            },
            "emisor": CAMPO_CON_CITA("string", "Nombre de quien emite el documento"),
            "nif": CAMPO_CON_CITA("string", "NIF/CIF del emisor tal como figura"),
            "fecha": CAMPO_CON_CITA("string", "Fecha del documento en formato AAAA-MM-DD"),
            "numero": CAMPO_CON_CITA("string", "Número o referencia del documento"),
            "importe_total": CAMPO_CON_CITA("number", "Importe total con impuestos, en euros"),
            "conceptos": {
                "type": "array",
                "description": "Líneas o conceptos principales del documento.",
                "items": {
                    "type": "object",
                    "properties": {
                        "descripcion": {"type": "string"},
                        "importe": {"type": ["number", "null"]},
                    },
                    "required": ["descripcion", "importe"],
                    "additionalProperties": False,
                },
            },
        },
        "required": [
            "tipo_documento",
            "emisor",
            "nif",
            "fecha",
            "numero",
            "importe_total",
            "conceptos",
        ],
        "additionalProperties": False,
    },
}

# ── Validación posterior: la IA propone, el código comprueba ───────────


def validar(datos: dict, nombre: str) -> dict:
    """Comprueba formatos y degrada a null lo que no cuadre, avisando."""
    fecha = datos.get("fecha", {}).get("valor")
    if fecha is not None and not re.fullmatch(r"\d{4}-\d{2}-\d{2}", str(fecha)):
        print(f"AVISO [{nombre}]: fecha '{fecha}' sin formato AAAA-MM-DD; se anula.", file=sys.stderr)
        datos["fecha"]["valor"] = None
    total = datos.get("importe_total", {}).get("valor")
    if total is not None and (not isinstance(total, (int, float)) or total < 0):
        print(f"AVISO [{nombre}]: importe_total '{total}' no válido; se anula.", file=sys.stderr)
        datos["importe_total"]["valor"] = None
    return datos


def extraer(client: "anthropic.Anthropic", texto: str, nombre: str) -> dict:
    respuesta = client.messages.create(
        model=MODELO,
        max_tokens=2048,
        system=SISTEMA,
        tools=[HERRAMIENTA],
        tool_choice={"type": "tool", "name": "registrar_datos"},
        messages=[{"role": "user", "content": f"Documento «{nombre}»:\n\n{texto}"}],
    )
    for bloque in respuesta.content:
        if bloque.type == "tool_use" and bloque.name == "registrar_datos":
            return validar(dict(bloque.input), nombre)
    raise RuntimeError("La API no devolvió la extracción esperada.")


def procesar_fichero(client, ruta: Path, salida: Path | None) -> bool:
    try:
        texto = ruta.read_text(encoding="utf-8", errors="replace").strip()
    except OSError as e:
        print(f"ERROR: no puedo leer {ruta}: {e}", file=sys.stderr)
        return False
    if not texto:
        print(f"AVISO: {ruta} está vacío; lo salto.", file=sys.stderr)
        return False
    if len(texto) > MAX_CARACTERES:
        print(f"AVISO: {ruta} recortado a {MAX_CARACTERES} caracteres.", file=sys.stderr)
        texto = texto[:MAX_CARACTERES]

    try:
        datos = extraer(client, texto, ruta.name)
    except anthropic.AuthenticationError:
        sys.exit("Clave de API inválida o revocada. Revisa ANTHROPIC_API_KEY.")
    except anthropic.RateLimitError:
        print(f"ERROR: límite de peticiones en {ruta.name}; reintenta más tarde.", file=sys.stderr)
        return False
    except anthropic.APIStatusError as e:
        print(f"ERROR de la API ({e.status_code}) en {ruta.name}: {e.message}", file=sys.stderr)
        return False
    except anthropic.APIConnectionError:
        sys.exit("No hay conexión con la API. Revisa tu red y reintenta.")

    datos["_documento"] = ruta.name
    resultado = json.dumps(datos, ensure_ascii=False, indent=2)
    if salida:
        salida.mkdir(parents=True, exist_ok=True)
        destino = salida / (ruta.stem + ".json")
        destino.write_text(resultado + "\n", encoding="utf-8")
        print(f"OK {ruta.name} → {destino}")
    else:
        print(resultado)
    return True


def main() -> None:
    parser = argparse.ArgumentParser(description="Extrae datos estructurados de documentos .txt")
    parser.add_argument("fichero", nargs="?", help="Documento de texto a procesar")
    parser.add_argument("--carpeta", help="Procesa todos los .txt de una carpeta")
    parser.add_argument("--salida", help="Carpeta donde dejar los .json (uno por documento)")
    args = parser.parse_args()

    if not os.environ.get("ANTHROPIC_API_KEY"):
        sys.exit(
            "Falta la variable de entorno ANTHROPIC_API_KEY.\n"
            "Crea la clave en console.anthropic.com y expórtala antes de ejecutar."
        )

    client = anthropic.Anthropic()
    salida = Path(args.salida) if args.salida else None

    if args.carpeta:
        ficheros = sorted(Path(args.carpeta).glob("*.txt"))
        if not ficheros:
            sys.exit(f"No hay .txt en {args.carpeta}.")
        correctos = sum(procesar_fichero(client, f, salida) for f in ficheros)
        print(f"\nProcesados {correctos} de {len(ficheros)} documentos.", file=sys.stderr)
        sys.exit(0 if correctos == len(ficheros) else 1)

    if not args.fichero:
        sys.exit("Indica un fichero o usa --carpeta. Mira --help.")
    ok = procesar_fichero(client, Path(args.fichero), salida)
    sys.exit(0 if ok else 1)


if __name__ == "__main__":
    main()
